package roman

import "testing"

func TestToRoman(t *testing.T) {
	cases := map[int]string{1: "I", 4: "IV", 9: "IX", 14: "XIV", 40: "XL", 90: "XC", 399: "CCCXCIX", 1994: "MCMXCIV", 3999: "MMMCMXCIX"}
	for n, want := range cases {
		if got := ToRoman(n); got != want { t.Errorf("ToRoman(%d) = %q, want %q", n, got, want) }
	}
}

func TestFromRoman(t *testing.T) {
	cases := map[string]int{"I": 1, "IV": 4, "IX": 9, "XIV": 14, "XL": 40, "XC": 90, "MCMXCIV": 1994}
	for s, want := range cases {
		if got := FromRoman(s); got != want { t.Errorf("FromRoman(%q) = %d, want %d", s, got, want) }
	}
}

func TestRoundTrip(t *testing.T) {
	for n := 1; n <= 100; n++ {
		if got := FromRoman(ToRoman(n)); got != n {
			t.Errorf("round-trip failed for %d: got %d", n, got)
		}
	}
}
